"use client";
import { DragEvent, FormEvent, ReactNode, useEffect, useMemo, useState } from "react";

type Row = Record<string, string | number | boolean | null | undefined>;
type Data = { member?: Row; clients: Row[]; revenue: Row[]; pipeline: Row[]; calls: Row[]; meetings: Row[]; invoices: Row[]; payments: Row[]; agreements: Row[]; documents: Row[]; vendors: Row[]; members: Row[]; teamSummary: Row[]; pipelineSettings?: Row };
type Scope = "overall" | "team";
const blank: Data = { clients: [], revenue: [], pipeline: [], calls: [], meetings: [], invoices: [], payments: [], agreements: [], documents: [], vendors: [], members: [], teamSummary: [], pipelineSettings: { probabilities: '{"l1":20,"l2":50,"l3":100,"l4":100,"l5":100}' } };
const nav = ["Dashboard", "Clients", "Revenue", "Pipeline", "Calls", "Calendar", "Invoices", "Vendors", "Agreements", "Team"];
const stages = ["l1", "l2", "l3", "l4", "l5"];
const stageLabels: Record<string, string> = { l1: "L1 - Quotation Submitted", l2: "L2 - In Negotiation", l3: "L3 - Confirmed, Not Executed", l4: "L4 - Executed, Not Billed", l5: "L5 - Billed" };
const reports: Record<string, { target: number; mtd: number }> = { "Pratik Darji": { target: 1500000, mtd: 300000 }, "Yogesh Pawar": { target: 700000, mtd: 100000 }, "Mukesh Mishra": { target: 1500000, mtd: 250000 }, "Omkar Sawant": { target: 1300000, mtd: 200000 } };
const m = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 });
const s = (r: Row | undefined, k: string) => String(r?.[k] ?? "");
const n = (r: Row | undefined, k: string) => Number(r?.[k] || 0) / 100;
const projected = (r: Row | undefined) => r?.projectedRevenueMinor !== undefined && r?.projectedRevenueMinor !== null ? n(r, "projectedRevenueMinor") : n(r, "revenueMinor");
const projectedMargin = (r: Row | undefined) => r?.projectedMarginMinor !== undefined && r?.projectedMarginMinor !== null ? n(r, "projectedMarginMinor") : n(r, "marginMinor");
const actual = (r: Row | undefined) => r?.actualRevenueMinor === null || r?.actualRevenueMinor === undefined || r?.actualRevenueMinor === "" ? null : n(r, "actualRevenueMinor");
const actualMargin = (r: Row | undefined) => r?.actualMarginMinor === null || r?.actualMarginMinor === undefined || r?.actualMarginMinor === "" ? null : n(r, "actualMarginMinor");
const revenueMonth = (r: Row | undefined) => s(r, "revenueMonth") || s(r, "entryDate").slice(0, 7);
const monthLabel = (month: string) => { if (!/^\d{4}-\d{2}$/.test(month)) return month || "—"; const [year, number] = month.split("-").map(Number); return new Date(year, number - 1, 1).toLocaleDateString("en-IN", { month: "long", year: "numeric" }); };
const revenueStatus = (r: Row | undefined) => { const a = actual(r); const p = projected(r); return a === null || a === 0 ? "Projected" : a < p ? "Partly received" : "Received"; };
const today = () => new Date().toISOString().slice(0, 10);
const fmtDate = (v: string) => { if (!v) return "—"; const d = new Date(v.length === 10 ? v + "T00:00:00" : v); return Number.isNaN(d.getTime()) ? v : d.toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" }); };
const addDays = (v: string, days: number) => { const d = new Date(v + "T00:00:00"); d.setDate(d.getDate() + days); return d.toISOString().slice(0, 10); };
const displayName = (r: Row | undefined) => s(r, "fullName") === "Durgesh Mishra" ? "Durgessh Misra" : s(r, "fullName");
const displayEmail = (r: Row | undefined) => { const email = s(r, "email"); return email.includes("@secondmedic.com") || email.includes("@imported.local") || email.includes("@team.local") ? "Email not provided" : email || "Email not provided"; };
const icons: Record<string, string> = { Dashboard: "⌂", Clients: "◌", Revenue: "₹", Pipeline: "↗", Calls: "⌁", Calendar: "□", Invoices: "▤", Vendors: "◈", Agreements: "◫", Team: "♧" };
function actionLabel(view: string) { if (view === "Revenue") return "Add revenue"; if (view === "Pipeline") return "Add opportunity"; if (view === "Calls") return "Log call"; if (view === "Calendar") return "Fix meeting"; if (view === "Invoices") return "Add invoice"; if (view === "Vendors") return "Add vendor"; if (view === "Agreements") return "Add agreement"; return "Add client"; }
function modalTitle(view: string) { if (view === "Revenue") return "Record revenue and margin"; if (view === "Pipeline") return "Add pipeline opportunity"; if (view === "Calls") return "Log cold call"; if (view === "Calendar") return "Fix client meeting"; if (view === "Invoices") return "Add invoice"; if (view === "Vendors") return "Add vendor payable"; if (view === "Agreements") return "Add agreement"; return "Add a client"; }

export default function Home() {
  const [data, setData] = useState<Data>(blank);
  const [view, setView] = useState("Dashboard");
  const [scope, setScope] = useState<Scope>("overall");
  const [selectedMember, setSelectedMember] = useState("");
  const [notice, setNotice] = useState("");
  const [loading, setLoading] = useState(true);
  const [recordOpen, setRecordOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Row | null>(null);
  const [agreementOpen, setAgreementOpen] = useState<Row | null>(null);
  const [callsOpen, setCallsOpen] = useState(false);
  const [callPreview, setCallPreview] = useState<{ row: Record<string, string>; error: string }[]>([]);
  const [teamOpen, setTeamOpen] = useState<string | null>(null);
  const [authOpen, setAuthOpen] = useState(false);
  const [calendarSeed, setCalendarSeed] = useState("");
  const [revenueActualOpen, setRevenueActualOpen] = useState<Row | null>(null);
  const [paymentOpen, setPaymentOpen] = useState<Row | null>(null);
  const [pipelineInvoiceOpen, setPipelineInvoiceOpen] = useState<Row | null>(null);
  const [pipelineSettingsOpen, setPipelineSettingsOpen] = useState(false);
  const [filters, setFilters] = useState<Record<string, string>>({ clientSearch: "", clientStaff: "all", clientStatus: "all", revenueStaff: "all", revenueRange: "this", revenueFrom: "", revenueTo: "", dashboardMonth: new Date().toISOString().slice(0, 7), pipelineStaff: "all", pipelineTeam: "all", invoiceFilter: "all", vendorSearch: "", vendorStaff: "all" });
  const [calendarMode, setCalendarMode] = useState<"month" | "week" | "day">("month");
  const [calendarDate, setCalendarDate] = useState(new Date());
  const [loadError, setLoadError] = useState("");
  const load = async () => { setLoading(true); setLoadError(""); const ctrl = new AbortController(); const timer = setTimeout(() => ctrl.abort(), 15000); try { const r = await fetch("/api/crm", { cache: "no-store", signal: ctrl.signal }); const j = await r.json(); if (!r.ok) throw new Error(j.error); setData(j); } catch (e) { const msg = e instanceof DOMException && e.name === "AbortError" ? "The server is taking too long to answer." : e instanceof Error ? e.message : "Could not load CRM data."; setLoadError(msg); } finally { clearTimeout(timer); setLoading(false); } };
  useEffect(() => { void load(); }, []);
  const clients = useMemo(() => Object.fromEntries(data.clients.map((row) => [s(row, "id"), row])), [data.clients]);
  const client = (id: string) => s(clients[id], "legalName") || "Unlinked prospect";
  const member = (id: string) => data.members.find((row) => s(row, "id") === id);
  const owner = (id: string) => displayName(member(id)) || "Unassigned";
  const paid = (id: string) => data.payments.filter((row) => s(row, "invoiceId") === id).reduce((sum, row) => sum + n(row, "amountMinor"), 0);
  const setFilter = (key: string, value: string) => setFilters((old) => ({ ...old, [key]: value }));
  const save = async (body: Record<string, unknown>, message: string) => { try { const r = await fetch("/api/crm", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) }); const j = await r.json(); if (!r.ok) throw new Error(j.error); setNotice(j.tempPassword ? message + " Temporary password: " + j.tempPassword : j.duplicate ? "Duplicate agreement skipped; existing record kept." : message); await load(); return j; } catch (e) { setNotice(e instanceof Error ? e.message : "Could not save record."); return null; } };
  async function submit(event: FormEvent<HTMLFormElement>, action: string) { event.preventDefault(); const form = event.currentTarget; const fd = new FormData(form); const file = fd.get("file"); const body = Object.fromEntries(fd.entries()) as Record<string, unknown>; delete body.file; body.action = action; if (action === "invoice" && !body.dueDate && body.issueDate && body.clientId) body.dueDate = addDays(String(body.issueDate), Number(s(clients[String(body.clientId)], "paymentTermsDays")) || 30); const isCsv = file instanceof File && file.size > 0 && (/\\.csv$/i.test(file.name) || file.type === "text/csv"); if (isCsv && ["client", "invoice"].includes(action)) { body.action = action === "client" ? "bulk_clients" : "bulk_invoices"; body.csv = await file.text(); } const j = await save(body, "Saved successfully."); if (!j) return; if (file instanceof File && file.size && !isCsv && ["invoice", "agreement"].includes(action) && !j.duplicate) { const upload = new FormData(); upload.set("file", file); upload.set("clientId", String(body.clientId || "")); upload.set("entityId", String(j.id)); upload.set("entityType", action); await fetch("/api/upload", { method: "POST", body: upload }); } form.reset(); setRecordOpen(false); }
  async function saveClientEdit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string, unknown>; const stage = String(body.stage || ""); delete body.stage; body.action = "client_update"; body.clientId = s(editingClient, "id"); const j = await save(body, "Client updated. Linked records remain connected."); if (!j) return; setEditingClient(null); const deal = data.pipeline.find((row) => s(row, "clientId") === s(editingClient, "id") && s(row, "stage") !== "lost"); if (stage && deal && s(deal, "stage") !== stage) await movePipeline(s(deal, "id"), stage); }
  async function saveRevenueActual(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string, unknown>; body.action = "revenue_actual_update"; body.revenueId = s(revenueActualOpen, "id"); const j = await save(body, "Actual revenue updated."); if (j) setRevenueActualOpen(null); }
  async function movePipeline(id: string, stage: string) { if (stage === "l5") { const item = data.pipeline.find((row) => s(row, "id") === id); if (item) setPipelineInvoiceOpen(item); return; } await save({ action: "pipeline_update", pipelineId: id, stage }, "Pipeline stage updated."); }
  async function savePipelineInvoice(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string, unknown>; body.action = "pipeline_update"; body.pipelineId = s(pipelineInvoiceOpen, "id"); body.stage = "l5"; const j = await save(body, "Deal moved to L5 and invoice created."); if (j) setPipelineInvoiceOpen(null); }
  async function savePayment(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string, unknown>; body.action = "payment"; body.invoiceId = s(paymentOpen, "id"); body.clientId = s(paymentOpen, "clientId"); const j = await save(body, "Payment recorded and actual revenue updated."); if (j) setPaymentOpen(null); }
  async function savePipelineSettings(values: Record<string, string>) { const j = await save({ action: "pipeline_settings", probabilities: values }, "Pipeline probabilities updated."); if (j) setPipelineSettingsOpen(false); }
  async function saveAgreementDetails(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string, unknown>; body.action = "agreement_update"; body.agreementId = s(agreementOpen, "id"); const j = await save(body, "Agreement details updated."); if (j) setAgreementOpen(null); }
  async function resetPassword(id: string) { await save({ action: "reset_password", memberId: id }, "Temporary password generated."); }
  async function removeMember(id: string) { await save({ action: "team_member_remove", memberId: id }, "Team member removed."); }
  function openMeeting(value: string) { setCalendarSeed(value + "T09:00"); setRecordOpen(true); }
  function parseCalls(file: File) { const reader = new FileReader(); reader.onload = () => { const lines = String(reader.result || "").split(/\r?\n/).map((line) => line.trim()).filter(Boolean); if (lines.length < 2) return setNotice("The file needs a header row and one call."); const headers = lines[0].split(",").map((header) => header.trim().replace(/^"|"$/g, "")); const seen = new Set<string>(); setCallPreview(lines.slice(1).map((line) => { const values = line.split(",").map((value) => value.trim().replace(/^"|"$/g, "")); const row = Object.fromEntries(headers.map((header, i) => [header, values[i] || ""])); const key = (row.clientId || row.client || row.prospectName) + "|" + row.calledAt + "|" + row.outcome; const error = !row.prospectName && !row.clientId && !row.client ? "Client or prospect is required" : !row.calledAt ? "Called at is required" : seen.has(key) ? "Duplicate row" : ""; seen.add(key); return { row, error }; })); }; reader.readAsText(file); }
  async function saveCalls() { const rows = callPreview.filter((entry) => !entry.error).map((entry) => entry.row); if (!rows.length) return setNotice("Fix preview errors before saving."); const j = await save({ action: "bulk_calls", rows }, "Calls imported."); if (j) { setCallsOpen(false); setCallPreview([]); } }
  function downloadTemplate() { const blob = new Blob(["clientId,prospectName,calledAt,outcome,durationSeconds,nextFollowUpAt,notes\n,Example Health,2026-10-15T10:30,connected,120,2026-10-16T11:00,Discussed proposal"], { type: "text/csv" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = "cold-call-template.csv"; a.click(); }
  const options = <><option value="">Choose client</option>{data.clients.map((row) => <option key={s(row, "id")} value={s(row, "id")}>{s(row, "legalName")}</option>)}</>;
  const overdue = data.invoices.filter((row) => s(row, "dueDate") < today() && n(row, "totalMinor") > paid(s(row, "id")));
  const expiring = data.agreements.filter((row) => s(row, "expiryDate") && s(row, "expiryDate") <= addDays(today(), 60));
  const props = { data, client, owner, paid, overdue, expiring, scope, setScope, selectedMember, setSelectedMember, setEditingClient, setRevenueActual: setRevenueActualOpen, movePipeline, openMeeting, calendarMode, setCalendarMode, calendarDate, setCalendarDate, setAgreementOpen: setAgreementOpen, filters, setFilter, teamOpen, setTeamOpen, resetPassword, removeMember, currentMember: data.member, setPaymentOpen, setPipelineSettingsOpen, savePipelineSettings, paymentOpen, pipelineInvoiceOpen, setPipelineInvoiceOpen, savePayment, savePipelineInvoice, agreementOpen, saveAgreementDetails, pipelineSettingsOpen, setAgreementOpen, savePipelineSettings };
  return <main className="crm-shell"><aside className="crm-nav"><a className="logo" href="#top"><span>◈</span><div>Client<br/>Orbit</div></a><p className="workspace">SALES WORKSPACE</p><nav>{nav.map((item) => <button key={item} onClick={() => { setView(item); setRecordOpen(false); }} className={view === item ? "selected" : ""}><i>{icons[item]}</i>{item}</button>)}</nav><div className="profile"><b>{displayName(data.member) || "Loading profile"}</b><small>{s(data.member, "role") || "CRM member"}</small><button className="profile-link" onClick={() => setAuthOpen(true)}>Forgot password?</button></div></aside><section className="crm-main" id="top"><header className="topbar"><div><p className="kicker">{view === "Dashboard" ? "ADMIN SALES UPDATE" : "CRM WORKSPACE"}</p><h1>{view === "Dashboard" ? "Performance command center" : view}</h1><p>{view === "Dashboard" ? "One view for the whole business, each team and every individual." : "Manage " + view.toLowerCase() + " with a reliable shared history."}</p></div><div className="header-actions">{view === "Calls" && <><button className="ghost" onClick={() => setCallsOpen(true)}>Upload Excel/CSV</button><button className="ghost" onClick={downloadTemplate}>Sample template</button></>}{view !== "Dashboard" && view !== "Team" && <button className="ghost" onClick={() => void load()}>↻ Refresh</button>}{view !== "Dashboard" && view !== "Team" && <button className="primary" onClick={() => setRecordOpen(true)}>+ {actionLabel(view)}</button>}{(view === "Dashboard" || view === "Team") && <button className="ghost" onClick={() => void load()}>↻ Refresh</button>}</div></header>{notice && <div className="notice">● {notice}<button onClick={() => setNotice("")}>×</button></div>}{loading ? <div className="loading"><div className="spinner" aria-hidden="true"/>Loading secure CRM workspace…</div> : loadError ? <div className="loading error-state"><b>Could not load your data</b><p>{loadError}</p><button className="primary" onClick={() => void load()}>Retry</button></div> : <><View view={view} {...props}/>{recordOpen && <div className="record-modal-backdrop" onClick={() => setRecordOpen(false)}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={() => setRecordOpen(false)}>×</button><div className="entry-intro"><p className="kicker">FAST ENTRY</p><h2>{modalTitle(view)}</h2><p>Keep key details updated while the activity is fresh.</p></div><div className="entry-form">{form(view, options, data, submit, calendarSeed)}</div></section></div>}{editingClient && <ClientEditDialog client={editingClient} data={data} onClose={() => setEditingClient(null)} onSave={saveClientEdit}/>} {revenueActualOpen && <RevenueActualDialog revenue={revenueActualOpen} client={client} onClose={() => setRevenueActualOpen(null)} onSave={saveRevenueActual}/>} {callsOpen && <CallImportDialog preview={callPreview} onFile={parseCalls} onClose={() => { setCallsOpen(false); setCallPreview([]); }} onSave={saveCalls}/>} {teamOpen && <TeamMemberDialog team={teamOpen} onClose={() => setTeamOpen(null)} onSave={async (body) => { const j = await save({ ...body, action: "team_member_add", teamName: teamOpen }, "Team member added."); if (j) setTeamOpen(null); }}/>} {agreementOpen && <AgreementPanel agreement={agreementOpen} data={data} client={client} onClose={() => setAgreementOpen(null)}/>} {authOpen && <AuthHelpDialog onClose={() => setAuthOpen(false)}/>}</>}</section></main>;
}

function View(p: any) {
  let screen: ReactNode;
  if (p.view === "Dashboard") screen = <Dashboard {...p}/>; else if (p.view === "Clients") screen = <Clients {...p}/>; else if (p.view === "Revenue") screen = <Revenue {...p}/>; else if (p.view === "Pipeline") screen = <Pipeline {...p}/>; else if (p.view === "Calls") screen = <Calls {...p}/>; else if (p.view === "Calendar") screen = <Calendar {...p}/>; else if (p.view === "Invoices") screen = <Invoices {...p}/>; else if (p.view === "Vendors") screen = <Vendors {...p}/>; else if (p.view === "Agreements") screen = <Agreements {...p}/>; else screen = <Team {...p}/>;
  return <>{screen}{p.agreementOpen && <AgreementPanel agreement={p.agreementOpen} client={p.client} onClose={() => p.setAgreementOpen(null)} onSave={p.saveAgreementDetails}/>} {p.paymentOpen && <PaymentDialog invoice={p.paymentOpen} onClose={() => p.setPaymentOpen(null)} onSave={p.savePayment}/>} {p.pipelineInvoiceOpen && <PipelineInvoiceDialog deal={p.pipelineInvoiceOpen} onClose={() => p.setPipelineInvoiceOpen(null)} onSave={p.savePipelineInvoice}/>} {p.pipelineSettingsOpen && <PipelineSettingsDialog settings={p.data.pipelineSettings} onClose={() => p.setPipelineSettingsOpen(false)} onSave={p.savePipelineSettings}/>}</>;
}

function Dashboard(p: any) {
  const [showFocus, setShowFocus] = useState(false); const [showPipeline, setShowPipeline] = useState(false);
  const staff = p.data.members.filter((row: Row) => s(row, "role") !== "admin");
  const chosen = staff.find((row: Row) => s(row, "id") === p.selectedMember) || staff[0];
  const teams = [...new Map(staff.map((row: Row) => [s(row, "teamName"), row])).values()];
  const scoped = p.scope === "overall" ? staff : staff.filter((row: Row) => s(row, "teamName") === s(chosen, "teamName"));
  const month = p.filters.dashboardMonth || new Date().toISOString().slice(0, 7); const ids = new Set(scoped.map((row: Row) => s(row, "id")));
  const confirmed = p.data.pipeline.filter((row: Row) => ids.has(s(row, "ownerMemberId")) && ["l3", "l4", "l5"].includes(s(row, "stage")));
  const backup = p.data.pipeline.filter((row: Row) => ids.has(s(row, "ownerMemberId")) && ["l1", "l2"].includes(s(row, "stage")));
  const revenue = p.data.revenue.filter((row: Row) => ids.has(s(row, "ownerMemberId")) && revenueMonth(row) === month);
  const scopedClientIds = new Set(p.data.clients.filter((row: Row) => ids.has(s(row, "ownerMemberId"))).map((row: Row) => s(row, "id")));
  const scopedInvoices = p.data.invoices.filter((row: Row) => scopedClientIds.has(s(row, "clientId")));
  const mtd = p.data.payments.filter((row: Row) => s(row, "receivedOn").startsWith(month) && scopedInvoices.some((invoice: Row) => s(invoice, "id") === s(row, "invoiceId"))).reduce((sum: number, row: Row) => sum + n(row, "amountMinor"), 0);
  const target = scoped.reduce((sum: number, row: Row) => sum + (reports[s(row, "fullName")]?.target || 0), 0);
  const total = confirmed.reduce((sum: number, row: Row) => sum + n(row, "expectedRevenueMinor"), 0); const margin = confirmed.reduce((sum: number, row: Row) => sum + n(row, "expectedMarginMinor"), 0);
  const remaining = confirmed.reduce((sum: number, row: Row) => { const linked = p.data.revenue.find((rev: Row) => s(rev, "id") === s(row, "revenueId")); return sum + Math.max(0, n(row, "expectedRevenueMinor") - (actual(linked) || 0)); }, 0);
  const projectedByEnd = mtd + remaining; const pipeTotal = backup.reduce((sum: number, row: Row) => sum + n(row, "expectedRevenueMinor") * Number(row.probability || 0) / 100, 0);
  const focusRows = confirmed.slice().sort((a: Row, b: Row) => n(b, "expectedRevenueMinor") - n(a, "expectedRevenueMinor")); const pipelineVisible = showPipeline ? backup : backup.slice(0, 10); const focusVisible = showFocus ? focusRows : focusRows.slice(0, 8);
  const label = p.scope === "overall" ? "All teams" : s(chosen, "teamName"); const paymentRows = scopedInvoices.filter((row: Row) => s(row, "dueDate").startsWith(month)).slice().sort((a: Row, b: Row) => s(a, "dueDate").localeCompare(s(b, "dueDate")));
  return <section className="admin-update"><div className="admin-switch"><div><p className="kicker">ADMIN SALES UPDATE · {monthLabel(month)}</p><h2>{label}</h2><p>{p.scope === "overall" ? "Combined reporting across all four BD teams." : "Team performance for " + label + ". Sellers: " + scoped.map((row: Row) => displayName(row)).join(", ")}</p></div><div className="scope-tabs"><button className={p.scope === "overall" ? "on" : ""} onClick={() => p.setScope("overall")}>Overall</button><button className={p.scope === "team" ? "on" : ""} onClick={() => p.setScope("team")}>Team-wise</button>{p.scope === "team" && <select aria-label="Choose team" value={s(chosen, "id")} onChange={(e) => p.setSelectedMember(e.target.value)}>{teams.map((row: Row) => <option key={s(row, "id")} value={s(row, "id")}>{s(row, "teamName")}</option>)}</select>}<label className="dashboard-month">Revenue month<input type="month" value={month} onChange={(e) => p.setFilter("dashboardMonth", e.target.value)}/></label></div></div>
    <div className="update-head"><div className="update-brand"><b>{p.scope === "overall" ? "All BD Teams" : label}</b><span>SALES UPDATE — {monthLabel(month).toUpperCase()}</span><em>Focus. Execute. Achieve.</em></div><Stat icon="🎯" label="Target" value={m.format(target)}/><Stat icon="◒" label="MTD" value={m.format(mtd)} tone="mint"/><Stat icon="◔" label="Balance" value={m.format(Math.max(0, target - mtd))} tone="sand"/><Stat icon="🏅" label={"Projected by " + monthLabel(month)} value={m.format(projectedByEnd)} tone="blue"/><div className="days-left"><b>{Math.max(0, new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0).getDate() - new Date().getDate())}</b><span>DAYS LEFT</span></div></div>
    <div className="update-progress"><div><span style={{ width: (target ? Math.min(100, Math.round(mtd / target * 100)) : 0) + "%" }}>{target ? Math.round(mtd / target * 100) : 0}%</span></div><small>{m.format(mtd)} <b>{m.format(target)}</b></small></div>
    <div className="update-grid"><UpdatePanel tone="green" title="CONFIRMED ACCOUNTS (L3 TO L5)"><MiniHeader cols={["Party", "Value", "Margin"]}/>{focusVisible.map((row: Row) => <MiniRow key={s(row, "id")} cols={[p.client(s(row, "clientId")), n(row, "expectedRevenueMinor") ? m.format(n(row, "expectedRevenueMinor")) : "Value TBD", n(row, "expectedRevenueMinor") ? Math.round(n(row, "expectedMarginMinor") / n(row, "expectedRevenueMinor") * 100) + "%" : "—"]}/>)}{focusRows.length > 8 && <button className="view-more" onClick={() => setShowFocus((value) => !value)}>{showFocus ? "Show less ↑" : "View more ↓"}</button>}<div className="mini-total"><b>Total</b><strong>{m.format(total)}</strong><strong>{m.format(margin)}</strong></div></UpdatePanel><UpdatePanel tone="navy" title="BACKUP / PIPELINE"><MiniHeader cols={["Party", "Value", "Stage"]}/>{pipelineVisible.map((row: Row) => <MiniRow key={s(row, "id")} cols={[p.client(s(row, "clientId")), n(row, "expectedRevenueMinor") ? m.format(n(row, "expectedRevenueMinor")) : "Value TBD", stageLabels[s(row, "stage")] || s(row, "stage")]}/>)}{backup.length > 10 && <button className="view-more" onClick={() => setShowPipeline((value) => !value)}>{showPipeline ? "Show less ↑" : "View more ↓"}</button>}<div className="mini-total"><b>Total</b><strong>{m.format(pipeTotal)}</strong><span>weighted opportunity</span></div></UpdatePanel></div>
    <div className="update-bottom"><UpdatePanel tone="red" title={"PAYMENT DETAILS IN " + monthLabel(month)}><div className="payment-list"><MiniHeader cols={["Client", "Amount", "Due date", "Status"]}/>{paymentRows.slice(0, 10).map((row: Row) => <MiniRow key={s(row, "id")} cols={[p.client(s(row, "clientId")), m.format(Math.max(0, n(row, "totalMinor") - p.paid(s(row, "id")))), fmtDate(s(row, "dueDate")), "Expected"]}/>)}</div></UpdatePanel></div>{p.scope === "overall" && <OverallSummary data={p.data} month={month} paid={p.paid}/>}</section>;
}

function OverallSummary({ data, month, paid }: { data: Data; month: string; paid: (id: string) => number }) { return <section className="team-performance-summary"><div><p className="kicker">OVERALL TEAM BREAKDOWN</p><h2>All four BD teams</h2><p>Target, payments received and confirmed projected revenue for {monthLabel(month)}.</p></div><div className="team-performance-grid">{Object.entries(reports).map(([name, report]) => { const member = data.members.find((row) => s(row, "fullName") === name); const ids = new Set(data.members.filter((row) => s(row, "teamName") === s(member, "teamName")).map((row) => s(row, "id"))); const clients = new Set(data.clients.filter((row) => ids.has(s(row, "ownerMemberId"))).map((row) => s(row, "id"))); const invoiceIds = new Set(data.invoices.filter((row) => clients.has(s(row, "clientId"))).map((row) => s(row, "id"))); const mtd = data.payments.filter((row) => invoiceIds.has(s(row, "invoiceId")) && s(row, "receivedOn").startsWith(month)).reduce((sum: number, row: Row) => sum + n(row, "amountMinor"), 0); const projected = data.pipeline.filter((row) => ids.has(s(row, "ownerMemberId")) && ["l3", "l4", "l5"].includes(s(row, "stage"))).reduce((sum: number, row: Row) => sum + n(row, "expectedRevenueMinor"), 0); return <article key={name}><b>{s(member, "teamName") || name}</b><span>{name}</span><strong>Target {m.format(report.target)}</strong><strong>MTD {m.format(mtd)}</strong><strong>Projected {m.format(projected)}</strong></article>; })}</div></section>; }

function Panel({ title, eyebrow, children, className = "" }: { title: string; eyebrow?: string; children: ReactNode; className?: string }) { return <section className={"data-panel " + className}><div className="panel-title">{eyebrow && <p className="kicker">{eyebrow}</p>}<h2>{title}</h2></div>{children}</section>; }
function Toolbar({ children }: { children: ReactNode }) { return <div className="table-toolbar">{children}</div>; }
function Select({ label, value, onChange, children }: { label: string; value: string; onChange: (v: string) => void; children: ReactNode }) { return <label className="filter-field"><span>{label}</span><select value={value} onChange={(e) => onChange(e.target.value)}>{children}</select></label>; }
function Tag({ children, tone = "mint" }: { children: ReactNode; tone?: string }) { return <span className={"status-tag " + tone}>{children}</span>; }
function TableHead({ cols, className = "" }: { cols: string[]; className?: string }) { return <div className={"table-head " + className}>{cols.map((col) => <b key={col}>{col}</b>)}</div>; }
function Empty({ children = "No records match these filters." }: { children?: ReactNode }) { return <div className="empty-state">{children}</div>; }
function Stat({ icon, label, value, tone = "blue" }: { icon: string; label: string; value: string; tone?: string }) { return <article className={"stat-card " + tone}><span>{icon}</span><div><small>{label}</small><strong>{value}</strong></div></article>; }
function UpdatePanel({ tone, title, children }: { tone: string; title: string; children: ReactNode }) { return <section className={"update-panel " + tone}><h3>{title}</h3><div className="update-panel-body">{children}</div></section>; }
function MiniHeader({ cols }: { cols: string[] }) { return <div className="mini-head">{cols.map((col) => <b key={col}>{col}</b>)}</div>; }
function MiniRow({ cols }: { cols: string[] }) { return <div className="mini-row">{cols.map((col, i) => <span key={i}>{col}</span>)}</div>; }

function Clients(p: any) {
  const rows = p.data.clients.filter((row: Row) => (!p.filters.clientSearch || s(row, "legalName").toLowerCase().includes(p.filters.clientSearch.toLowerCase())) && (p.filters.clientStaff === "all" || s(row, "ownerMemberId") === p.filters.clientStaff) && (p.filters.clientStatus === "all" || s(row, "status") === p.filters.clientStatus));
  return <Panel title="Client list" eyebrow="LINKED CUSTOMER RECORDS"><Toolbar><input placeholder="Search clients" value={p.filters.clientSearch} onChange={(e) => p.setFilter("clientSearch", e.target.value)}/><Select label="Staff" value={p.filters.clientStaff} onChange={(v) => p.setFilter("clientStaff", v)}><option value="all">All staff</option>{p.data.members.filter((r: Row) => s(r, "role") !== "admin").map((r: Row) => <option key={s(r, "id")} value={s(r, "id")}>{displayName(r)}</option>)}</Select><Select label="Status" value={p.filters.clientStatus} onChange={(v) => p.setFilter("clientStatus", v)}><option value="all">All statuses</option>{["prospect", "active", "on_hold", "won", "lost"].map((v) => <option key={v} value={v}>{v.replaceAll("_", " ")}</option>)}</Select></Toolbar><div className="data-table client-table"><TableHead cols={["Client name", "Staff (owner)", "Projected revenue", "Actual revenue", "Amount due", "Payment terms", "Status", "Last edited", "Actions"]}/>{rows.length ? rows.map((row: Row) => { const owner = p.owner(s(row, "ownerMemberId")); const projectedValue = p.data.revenue.filter((x: Row) => s(x, "clientId") === s(row, "id")).reduce((sum: number, x: Row) => sum + projected(x), 0); const actualValue = p.data.revenue.filter((x: Row) => s(x, "clientId") === s(row, "id")).reduce((sum: number, x: Row) => sum + (actual(x) || 0), 0); const due = p.data.invoices.filter((x: Row) => s(x, "clientId") === s(row, "id")).reduce((sum: number, x: Row) => sum + Math.max(0, n(x, "totalMinor") - p.paid(s(x, "id"))), 0); const edited = "by " + (owner || "staff") + " on " + fmtDate(s(row, "updatedAt") || s(row, "createdAt")); return <div className="table-row" key={s(row, "id")}><strong>{s(row, "legalName")}</strong><span>{owner}</span><span>{m.format(projectedValue)}</span><span>{m.format(actualValue)}</span><span>{m.format(due)}</span><span>Net {s(row, "paymentTermsDays") || "30"}</span><span><Tag tone={s(row, "status") === "active" ? "mint" : "blue"}>{s(row, "status") || "prospect"}</Tag></span><small>{edited}</small><button className="mini-link" title={edited} onClick={() => p.setEditingClient(row)}>Edit / View</button></div>; }) : <Empty/>}</div></Panel>;
}

function RevenueLegacy(p: any) {
  const now = new Date(), month = now.toISOString().slice(0, 7), prev = new Date(now.getFullYear(), now.getMonth() - 1, 1).toISOString().slice(0, 7); const range = p.filters.revenueRange; const rows = p.data.revenue.filter((row: Row) => (p.filters.revenueStaff === "all" || s(row, "ownerMemberId") === p.filters.revenueStaff) && (range === "this" ? s(row, "entryDate").startsWith(month) : range === "last" ? s(row, "entryDate").startsWith(prev) : (!p.filters.revenueFrom || s(row, "entryDate") >= p.filters.revenueFrom) && (!p.filters.revenueTo || s(row, "entryDate") <= p.filters.revenueTo))); const total = rows.reduce((sum: number, r: Row) => sum + n(r, "revenueMinor"), 0), projected = p.data.pipeline.filter((r: Row) => p.filters.revenueStaff === "all" || s(r, "ownerMemberId") === p.filters.revenueStaff).reduce((sum: number, r: Row) => sum + n(r, "expectedRevenueMinor"), 0), margin = rows.reduce((sum: number, r: Row) => sum + n(r, "marginMinor"), 0); return <Panel title="Revenue and margin" eyebrow="DATE-WISE PERFORMANCE"><Toolbar><Select label="Staff" value={p.filters.revenueStaff} onChange={(v) => p.setFilter("revenueStaff", v)}><option value="all">All staff</option>{p.data.members.filter((r: Row) => s(r, "role") !== "admin").map((r: Row) => <option key={s(r, "id")} value={s(r, "id")}>{displayName(r)}</option>)}</Select><Select label="Date range" value={range} onChange={(v) => p.setFilter("revenueRange", v)}><option value="this">This month</option><option value="last">Last month</option><option value="custom">Custom</option></Select>{range === "custom" && <><input type="date" value={p.filters.revenueFrom} onChange={(e) => p.setFilter("revenueFrom", e.target.value)}/><input type="date" value={p.filters.revenueTo} onChange={(e) => p.setFilter("revenueTo", e.target.value)}/></>}</Toolbar><div className="summary-cards"><Stat icon="₹" label="Total revenue (current filter)" value={m.format(total)}/><Stat icon="↗" label="Projected revenue" value={m.format(projected)} tone="mint"/><Stat icon="✓" label="Actual revenue" value={m.format(total)} tone="sand"/><Stat icon="%" label="Margin" value={m.format(margin)} tone="violet"/></div><div className="data-table revenue-table"><TableHead cols={["Client", "Staff", "Record date", "Revenue", "Margin %", "Actual revenue", "Actual margin"]}/>{rows.length ? rows.map((row: Row) => { const revenue = n(row, "revenueMinor"), marginValue = n(row, "marginMinor"); return <div className="table-row" key={s(row, "id")}><strong>{p.client(s(row, "clientId"))}</strong><span>{p.owner(s(row, "ownerMemberId"))}</span><span>{fmtDate(s(row, "entryDate"))}</span><span>{m.format(revenue)}</span><span>{revenue ? Math.round(marginValue / revenue * 100) : 0}%</span><span>{s(row, "status") === "approved" ? m.format(revenue) : "Pending approval"}</span><span>{s(row, "status") === "approved" ? m.format(marginValue) : "—"}</span></div>; }) : <Empty/>}</div></Panel>;
}

function Revenue(p: any) {
  const now = new Date();
  const currentMonth = now.toISOString().slice(0, 7);
  const previousMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1).toISOString().slice(0, 7);
  const range = p.filters.revenueRange;
  const rows = p.data.revenue.filter((row: Row) => {
    if (p.filters.revenueStaff !== "all" && s(row, "ownerMemberId") !== p.filters.revenueStaff) return false;
    const month = revenueMonth(row);
    if (range === "this") return month === currentMonth;
    if (range === "last") return month === previousMonth;
    return (!p.filters.revenueFrom || s(row, "entryDate") >= p.filters.revenueFrom) && (!p.filters.revenueTo || s(row, "entryDate") <= p.filters.revenueTo);
  });
  const projectedRevenue = rows.reduce((sum: number, row: Row) => sum + projected(row), 0);
  const actualRevenue = rows.reduce((sum: number, row: Row) => sum + (actual(row) || 0), 0);
  const projectedMarginValue = rows.reduce((sum: number, row: Row) => sum + projectedMargin(row), 0);
  const actualMarginValue = rows.reduce((sum: number, row: Row) => sum + (actualMargin(row) || 0), 0);
  return <Panel title="Revenue and margin" eyebrow="DATE-WISE PERFORMANCE"><Toolbar><Select label="Staff" value={p.filters.revenueStaff} onChange={(v) => p.setFilter("revenueStaff", v)}><option value="all">All staff</option>{p.data.members.filter((r: Row) => s(r, "role") !== "admin").map((r: Row) => <option key={s(r, "id")} value={s(r, "id")}>{displayName(r)}</option>)}</Select><Select label="Date range" value={range} onChange={(v) => p.setFilter("revenueRange", v)}><option value="this">This month</option><option value="last">Last month</option><option value="custom">Custom</option></Select>{range === "custom" && <><input type="date" value={p.filters.revenueFrom} onChange={(e) => p.setFilter("revenueFrom", e.target.value)}/><input type="date" value={p.filters.revenueTo} onChange={(e) => p.setFilter("revenueTo", e.target.value)}/></>}</Toolbar><div className="summary-cards"><Stat icon="↗" label="Projected revenue" value={m.format(projectedRevenue)} tone="mint"/><Stat icon="✓" label="Actual revenue" value={m.format(actualRevenue)} tone="sand"/><Stat icon="%" label="Projected margin" value={m.format(projectedMarginValue)} tone="violet"/><Stat icon="%" label="Actual margin" value={m.format(actualMarginValue)} tone="blue"/></div><div className="data-table revenue-table"><TableHead cols={["Client", "Staff", "Revenue month", "Projected revenue", "Margin %", "Projected margin", "Actual revenue", "Actual margin", "Status", "Updated actual", "Actions"]}/>{rows.length ? rows.map((row: Row) => { const projectedValue = projected(row), projectedMarginValue = projectedMargin(row), actualValue = actual(row), actualMarginValue = actualMargin(row), updatedBy = p.owner(s(row, "actualUpdatedByMemberId")); return <div className="table-row" key={s(row, "id")}><strong>{p.client(s(row, "clientId"))}</strong><span>{p.owner(s(row, "ownerMemberId"))}</span><span>{monthLabel(revenueMonth(row))}</span><span>{m.format(projectedValue)}</span><span>{projectedValue ? Math.round(projectedMarginValue / projectedValue * 100) : 0}%</span><span>{m.format(projectedMarginValue)}</span><span>{actualValue === null ? "-" : m.format(actualValue)}</span><span>{actualMarginValue === null ? "-" : m.format(actualMarginValue)}</span><span><Tag tone={revenueStatus(row) === "Received" ? "mint" : revenueStatus(row) === "Partly received" ? "amber" : "blue"}>{revenueStatus(row)}</Tag></span><small>{s(row, "actualUpdatedAt") ? "by " + updatedBy + " on " + fmtDate(s(row, "actualUpdatedAt")) : "—"}</small><button className="mini-link" onClick={() => p.setRevenueActual(row)}>Update actual</button></div>; }) : <Empty/>}</div></Panel>;
}

function Pipeline(p: any) { const rows = p.data.pipeline.filter((row: Row) => s(row, "stage") !== "lost" && (p.filters.pipelineStaff === "all" || s(row, "ownerMemberId") === p.filters.pipelineStaff) && (p.filters.pipelineTeam === "all" || s(p.data.members.find((m: Row) => s(m, "id") === s(row, "ownerMemberId")), "teamName") === p.filters.pipelineTeam)); const lost = p.data.pipeline.filter((row: Row) => s(row, "stage") === "lost"); const teams = [...new Set(p.data.members.map((r: Row) => s(r, "teamName")).filter(Boolean))]; const probabilities = (() => { try { return JSON.parse(s(p.data.pipelineSettings, "probabilities")); } catch { return { l1: 20, l2: 50, l3: 100, l4: 100, l5: 100 }; } })(); return <Panel title="Pipeline board" eyebrow="L1 TO L5 · DRAG TO UPDATE STAGE"><Toolbar><Select label="Staff" value={p.filters.pipelineStaff} onChange={(v) => p.setFilter("pipelineStaff", v)}><option value="all">All staff</option>{p.data.members.filter((r: Row) => s(r, "role") !== "admin").map((r: Row) => <option key={s(r, "id")} value={s(r, "id")}>{displayName(r)}</option>)}</Select><Select label="Team" value={p.filters.pipelineTeam} onChange={(v) => p.setFilter("pipelineTeam", v)}><option value="all">All teams</option>{teams.map((team) => <option key={team} value={team}>{team}</option>)}</Select>{s(p.currentMember, "role") === "admin" && <button className="ghost" onClick={() => p.setPipelineSettingsOpen(true)}>Stage probabilities</button>}</Toolbar><div className="kanban enhanced-kanban">{stages.map((stage) => { const cards = rows.filter((r: Row) => s(r, "stage") === stage); const value = cards.reduce((sum: number, r: Row) => sum + n(r, "expectedRevenueMinor"), 0); return <div className="kanban-column" key={stage} onDragOver={(e) => e.preventDefault()} onDrop={(e) => { const id = e.dataTransfer.getData("text/plain"); if (id) void p.movePipeline(id, stage); }}><div className="kanban-column-title"><b>{stageLabels[stage]}</b><span>{m.format(value)}</span></div>{cards.map((row: Row) => <article className="pipeline-card" key={s(row, "id")} draggable onDragStart={(e: DragEvent<HTMLElement>) => e.dataTransfer.setData("text/plain", s(row, "id"))}><strong>{p.client(s(row, "clientId"))}</strong><span>{n(row, "expectedRevenueMinor") ? m.format(n(row, "expectedRevenueMinor")) : "Value TBD"}</span><small>{Number(row.probability || probabilities[stage] || 0)}% probability · {fmtDate(s(row, "expectedCloseDate"))}</small><em>{p.owner(s(row, "ownerMemberId"))}</em><button className="danger-link" onClick={(e) => { e.stopPropagation(); void p.movePipeline(s(row, "id"), "lost"); }}>Mark lost</button></article>)}</div>; })}</div><section className="lost-deals"><h3>Lost deals</h3>{lost.length ? lost.map((row: Row) => <div key={s(row, "id")}><b>{p.client(s(row, "clientId"))}</b><span>{n(row, "expectedRevenueMinor") ? m.format(n(row, "expectedRevenueMinor")) : "Value TBD"}</span><small>{p.owner(s(row, "ownerMemberId"))} · {fmtDate(s(row, "lostAt"))}</small></div>) : <Empty>No lost deals.</Empty>}</section></Panel>; }

function Calls(p: any) { return <Panel title="Cold calls" eyebrow="ACTIVITY LOG"><div className="data-table calls-table"><TableHead cols={["Client / prospect", "Staff", "Called at", "Outcome", "Next follow-up", "Notes"]}/>{p.data.calls.length ? p.data.calls.map((row: Row) => <div className="table-row" key={s(row, "id")}><strong>{s(row, "clientId") ? p.client(s(row, "clientId")) : s(row, "prospectName")}</strong><span>{p.owner(s(row, "callerMemberId"))}</span><span>{fmtDate(s(row, "calledAt"))}</span><span><Tag tone="blue">{s(row, "outcome").replaceAll("_", " ")}</Tag></span><span>{fmtDate(s(row, "nextFollowUpAt"))}</span><span>{s(row, "notes") || "—"}</span></div>) : <Empty>No calls have been logged yet.</Empty>}</div></Panel>; }

function Calendar(p: any) { const d = p.calendarDate as Date, year = d.getFullYear(), month = d.getMonth(), first = new Date(year, month, 1), start = new Date(year, month, 1 - first.getDay()), cells = Array.from({ length: 42 }, (_, i) => new Date(start.getFullYear(), start.getMonth(), start.getDate() + i)), events = p.data.meetings; const shift = (delta: number) => p.setCalendarDate(new Date(year, month + delta, d.getDate())); const dayEvents = (date: Date) => events.filter((e: Row) => s(e, "scheduledAt").slice(0, 10) === date.toISOString().slice(0, 10)); return <Panel title="Calendar" eyebrow="MEETINGS AND FOLLOW-UPS"><div className="calendar-toolbar"><button className="ghost" onClick={() => p.setCalendarDate(new Date())}>Today</button><button className="icon-button" onClick={() => shift(-1)}>‹</button><button className="icon-button" onClick={() => shift(1)}>›</button><b>{d.toLocaleDateString("en-IN", { month: "long", year: "numeric" })}</b><div className="segmented">{["month", "week", "day"].map((mode) => <button key={mode} className={p.calendarMode === mode ? "on" : ""} onClick={() => p.setCalendarMode(mode)}>{mode[0].toUpperCase() + mode.slice(1)}</button>)}</div></div>{p.calendarMode === "month" ? <div className="calendar-grid"><div className="calendar-weekdays">{["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => <b key={day}>{day}</b>)}</div><div className="month-cells">{cells.map((date) => <button className={date.getMonth() === month ? "calendar-cell" : "calendar-cell muted"} key={date.toISOString()} onClick={() => p.openMeeting(date.toISOString().slice(0, 10))}><time>{date.getDate()}</time>{dayEvents(date).slice(0, 2).map((event: Row) => <span className="calendar-event" key={s(event, "id")}>{s(event, "title")}</span>)}</button>)}</div></div> : <div className="calendar-slots">{Array.from({ length: 12 }, (_, i) => 8 + i).map((hour) => <div className="time-slot" key={hour}><time>{String(hour).padStart(2, "0")}:00</time><div>{events.filter((event: Row) => { const date = s(event, "scheduledAt"); return date.slice(0, 10) === d.toISOString().slice(0, 10) && new Date(date).getHours() === hour; }).map((event: Row) => <article className="calendar-event large" key={s(event, "id")}><b>{s(event, "title")}</b><span>{s(event, "attendeeName")}</span></article>)}</div></div>)}</div>}</Panel>; }

function Invoices(p: any) { const list = p.data.invoices.filter((row: Row) => { const balance = Math.max(0, n(row, "totalMinor") - p.paid(s(row, "id"))), days = Math.ceil((new Date(s(row, "dueDate") + "T00:00:00").getTime() - new Date(today() + "T00:00:00").getTime()) / 86400000); return p.filters.invoiceFilter === "all" || (p.filters.invoiceFilter === "overdue" && balance > 0 && days < 0) || (p.filters.invoiceFilter === "due_soon" && balance > 0 && days >= 0 && days <= 3); }); const overdue = p.overdue.length; return <Panel title="Invoices and payments" eyebrow="COLLECTION CONTROL"><div className="invoice-summary"><Stat icon="!" label="Overdue invoices" value={String(overdue)} tone="red"/><Select label="Filter" value={p.filters.invoiceFilter} onChange={(v) => p.setFilter("invoiceFilter", v)}><option value="all">All invoices</option><option value="overdue">Overdue</option><option value="due_soon">Due soon</option></Select></div><div className="data-table invoice-table"><TableHead cols={["Invoice no.", "Client", "Staff", "Invoice date", "Due date", "Amount", "Paid", "Balance", "Status", "Actions"]}/>{list.length ? list.map((row: Row) => { const balance = Math.max(0, n(row, "totalMinor") - p.paid(s(row, "id"))), days = Math.ceil((new Date(s(row, "dueDate") + "T00:00:00").getTime() - new Date(today() + "T00:00:00").getTime()) / 86400000), isOverdue = balance > 0 && days < 0, soon = balance > 0 && days >= 0 && days <= 3; const status = balance <= 0 ? "Paid" : p.paid(s(row, "id")) > 0 ? "Part paid" : isOverdue ? "Overdue" : soon ? "Due soon" : "Sent"; return <div className={"table-row " + (isOverdue ? "overdue-row" : "")} key={s(row, "id")}><strong>{s(row, "invoiceNumber")}</strong><span>{p.client(s(row, "clientId"))}</span><span>{p.owner(s(row, "createdByMemberId"))}</span><span>{fmtDate(s(row, "issueDate"))}</span><span>{fmtDate(s(row, "dueDate"))}</span><span>{m.format(n(row, "totalMinor"))}</span><span>{m.format(p.paid(s(row, "id")))}</span><span>{m.format(balance)}</span><span><Tag tone={isOverdue ? "red" : soon ? "amber" : status === "Paid" ? "mint" : "blue"}>{isOverdue ? `Overdue (${Math.abs(days)} days)` : status}</Tag></span><button className="mini-link" onClick={() => p.setPaymentOpen(row)}>Record payment</button></div>; }) : <Empty/>}</div></Panel>; }

function Vendors(p: any) { const rows = p.data.vendors.filter((row: Row) => s(row, "vendorName").toLowerCase() !== "durgesh" && (!p.filters.vendorSearch || s(row, "vendorName").toLowerCase().includes(p.filters.vendorSearch.toLowerCase()) || p.client(s(row, "clientId")).toLowerCase().includes(p.filters.vendorSearch.toLowerCase())) && (p.filters.vendorStaff === "all" || s(row, "ownerMemberId") === p.filters.vendorStaff)); const total = rows.reduce((sum: number, row: Row) => sum + n(row, "amountMinor"), 0); return <Panel title="Vendors" eyebrow="PARTNER PAYABLES"><Toolbar><input placeholder="Search vendors or clients" value={p.filters.vendorSearch} onChange={(e) => p.setFilter("vendorSearch", e.target.value)}/><Select label="Staff" value={p.filters.vendorStaff} onChange={(v) => p.setFilter("vendorStaff", v)}><option value="all">All staff</option>{p.data.members.filter((r: Row) => s(r, "role") !== "admin").map((r: Row) => <option key={s(r, "id")} value={s(r, "id")}>{displayName(r)}</option>)}</Select></Toolbar><div className="data-table vendor-table"><TableHead cols={["Vendor name", "Client", "Amount payable", "Client payment received", "Due date", "Vendor status", "Staff"]}/>{rows.map((row: Row) => <div className="table-row" key={s(row, "id")}><strong>{s(row, "vendorName")}</strong><span>{p.client(s(row, "clientId"))}</span><span>{m.format(n(row, "amountMinor"))}</span><span><Tag tone={s(row, "clientPayment") === "yes" ? "mint" : "amber"}>{s(row, "clientPayment") === "yes" ? "Yes" : "No"}</Tag></span><span>{fmtDate(s(row, "dueDate"))}</span><span>{s(row, "status") || "Open"}</span><span>{p.owner(s(row, "ownerMemberId"))}</span></div>)}<div className="table-total"><b>Total payable</b><strong>{m.format(total)}</strong></div></div></Panel>; }

function Agreements(p: any) { const unique = [...new Map(p.data.agreements.map((row: Row) => [s(row, "clientId") + "|" + s(row, "title") + "|" + s(row, "valueMinor") + "|" + s(row, "expiryDate"), row])).values()]; return <Panel title="Agreements" eyebrow="CONTRACT CONTROL"><div className="data-table agreement-table"><TableHead cols={["Agreement", "Client", "Value", "Start date", "Expiry date", "Status", "Actions"]}/>{unique.map((row: Row) => { const days = Math.ceil((new Date(s(row, "expiryDate") + "T00:00:00").getTime() - new Date(today() + "T00:00:00").getTime()) / 86400000), soon = days >= 0 && days <= 60; return <div className={"table-row " + (soon ? "expiring-row" : "")} key={s(row, "id")}><strong>{s(row, "title")}</strong><span>{p.client(s(row, "clientId"))}</span><span>{m.format(n(row, "valueMinor"))}</span><span>{fmtDate(s(row, "effectiveDate"))}</span><span>{fmtDate(s(row, "expiryDate"))}{soon && <small className="expiry-note">Expiring within 60 days</small>}</span><span><Tag>{s(row, "status")}</Tag></span><button className="mini-link" onClick={() => p.setAgreementOpen(row)}>View</button></div>; })}</div></Panel>; }

function Team(p: any) { const staff = p.data.members.filter((row: Row) => s(row, "role") !== "admin" && s(row, "isActive") !== "false"), groups = [...new Set(staff.map((row: Row) => s(row, "teamName")))]; return <Panel title="Teams and access" eyebrow="PEOPLE DIRECTORY"><div className="expanded-teams">{groups.map((team) => { const members = staff.filter((row: Row) => s(row, "teamName") === team), head = members.find((row: Row) => s(row, "role") === "head") || members[0], canManage = s(p.currentMember, "role") === "admin" || s(p.currentMember, "id") === s(head, "id"); return <article className="team-card" key={team}><div><p className="kicker">TEAM</p><h3>{team}</h3><p>{members.length === 1 ? "1 active member" : members.length + " active members"} · Head: {displayName(head)}</p></div><button className="ghost" onClick={() => p.setTeamOpen(team)} disabled={!canManage}>+ Add member</button><div className="team-member-list">{members.map((member: Row) => <div key={s(member, "id")}><span><b>{displayName(member)}</b><small>{s(member, "role") === "head" ? "Team head" : "BD member"} · {displayEmail(member)}</small></span>{canManage && s(member, "id") !== s(head, "id") && <button className="danger-link" onClick={() => void p.removeMember(s(member, "id"))}>Remove</button>}{s(member, "role") !== "head" && s(p.currentMember, "role") === "admin" && <button className="mini-link" onClick={() => void p.resetPassword(s(member, "id"))}>Reset password</button>}</div>)}</div></article>; })}</div></Panel>; }

function form(view: string, options: ReactNode, data: Data, submit: (event: FormEvent<HTMLFormElement>, action: string) => void, seed: string) { const clients = options; const action = view === "Revenue" ? "revenue" : view === "Pipeline" ? "pipeline" : view === "Calls" ? "call" : view === "Calendar" ? "meeting" : view === "Invoices" ? "invoice" : view === "Vendors" ? "vendor" : view === "Agreements" ? "agreement" : "client"; return <form onSubmit={(e) => submit(e, action)} className="crm-form">{action === "client" && <><label>Client name<input name="legalName" required/></label><label>Contact name<input name="contactName"/></label><label>Contact email<input name="contactEmail" type="email"/></label><label>Phone<input name="contactPhone"/></label><label>Industry<input name="industry"/></label><label>City<input name="city"/></label><label>Payment terms (days)<input name="paymentTermsDays" type="number" min="0" defaultValue="30"/></label>{s(data.member, "role") === "admin" && <label>Owner (staff)<select name="ownerMemberId" defaultValue=""><option value="">Me</option>{data.members.filter((r) => s(r, "role") !== "admin").map((r) => <option key={s(r, "id")} value={s(r, "id")}>{displayName(r)}</option>)}</select></label>}<label>Status<select name="status"><option value="prospect">Prospect</option><option value="active">Active</option><option value="on_hold">On hold</option></select></label><label>Pipeline stage<select name="stage" defaultValue=""><option value="">No pipeline yet</option>{stages.slice(0, 2).map((st) => <option key={st} value={st}>{stageLabels[st]}</option>)}</select></label><label>Projected revenue (₹)<input name="projectedRevenue" type="number" min="0" step="1" placeholder="Optional"/></label><label>Margin %<input name="marginPercent" type="number" min="0" max="100" step="0.1" placeholder="Optional"/></label><label className="wide">Notes<textarea name="notes"/></label></>}{action === "revenue" && <><label>Client<select name="clientId" required>{clients}</select></label><label>Revenue month<input name="revenueMonth" type="month" defaultValue={today().slice(0, 7)} required/></label><label>Projected revenue<input name="projectedRevenue" type="number" min="0" required/></label><label>Margin %<input name="marginPercent" type="number" min="0" max="100" step="0.1" required/></label><label className="wide">Description<textarea name="description"/></label></>}{action === "pipeline" && <><label>Client<select name="clientId" required>{clients}</select></label><label>Opportunity title<input name="title" required/></label><label>Stage<select name="stage">{stages.map((stage) => <option key={stage} value={stage}>{stageLabels[stage]}</option>)}</select></label><label>Expected value<input name="expectedRevenue" type="number" min="0"/></label><label>Probability %<input name="probability" type="number" min="0" max="100" defaultValue="20"/></label><label>Expected close date<input name="expectedCloseDate" type="date"/></label><label className="wide">Next action<input name="nextAction"/></label></>}{action === "call" && <><label>Client<select name="clientId">{clients}</select></label><label>Prospect name<input name="prospectName"/></label><label>Called at<input name="calledAt" type="datetime-local" required/></label><label>Outcome<select name="outcome"><option value="connected">Connected</option><option value="no_answer">No answer</option><option value="callback">Callback</option><option value="not_interested">Not interested</option></select></label><label>Next follow-up<input name="nextFollowUpAt" type="datetime-local"/></label><label className="wide">Notes<textarea name="notes"/></label></>}{action === "meeting" && <><label>Meeting title<input name="title" required/></label><label>Client<select name="clientId">{clients}</select></label><label>Date and time<input name="scheduledAt" type="datetime-local" defaultValue={seed} required/></label><label>Attendee<input name="attendeeName"/></label><label>Duration (minutes)<input name="durationMinutes" type="number" defaultValue="30"/></label><label>Mode<select name="mode"><option value="in_person">In person</option><option value="video">Video</option><option value="phone">Phone</option></select></label><label className="wide">Agenda<textarea name="agenda"/></label></>}{action === "invoice" && <><label>Client<select name="clientId" required>{clients}</select></label><label>Invoice no.<input name="invoiceNumber" required/></label><label>Invoice date<input name="issueDate" type="date" defaultValue={today()} required/></label><label>Due date<input name="dueDate" type="date"/></label><label>Amount<input name="total" type="number" min="0" required/></label><label>Status<select name="status"><option value="sent">Sent</option><option value="paid">Paid</option><option value="partially_paid">Partially paid</option></select></label></>}{action === "vendor" && <><label>Vendor name<input name="vendorName" required/></label><label>Client<select name="clientId" required>{clients}</select></label><label>Amount payable<input name="amount" type="number" min="0" required/></label><label>Client payment<select name="clientPayment"><option value="no">No</option><option value="yes">Yes</option></select></label><label>Due date<input name="dueDate" type="date" required/></label><label className="wide">Notes<textarea name="notes"/></label></>}{action === "agreement" && <><label>Client<select name="clientId" required>{clients}</select></label><label>Agreement title<input name="title" required/></label><label>Agreement no.<input name="agreementNumber"/></label><label>Start date<input name="effectiveDate" type="date"/></label><label>Expiry date<input name="expiryDate" type="date"/></label><label>Value<input name="value" type="number" min="0"/></label><label className="wide">Summary / key clauses<textarea name="summary"/></label><label>Payment terms<textarea name="paymentTerms"/></label><label>Renewal terms<textarea name="renewalTerms"/></label><label className="wide">Attach file<input name="file" type="file"/></label></>}{action === "client" && <label className="wide">Upload CSV<input name="file" type="file" accept=".csv,text/csv"/></label>}<div className="form-actions"><button type="submit" className="primary">Save {view === "Calls" ? "call" : view === "Clients" ? "client" : view.toLowerCase()}</button></div></form>; }

function ClientEditDialog({ client, data, onClose, onSave }: { client: Row; data: Data; onClose: () => void; onSave: (e: FormEvent<HTMLFormElement>) => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">CLIENT RECORD</p><h2>Edit client</h2><p>Correct the name once and all linked revenue, pipeline, invoices and payments continue using the same client ID.</p></div><form className="crm-form" onSubmit={onSave}><label>Client name<input name="legalName" defaultValue={s(client, "legalName")} required/></label><label>Contact name<input name="contactName" defaultValue={s(client, "contactName")}/></label><label>Contact email<input name="contactEmail" defaultValue={s(client, "contactEmail")}/></label><label>Phone<input name="contactPhone" defaultValue={s(client, "contactPhone")}/></label><label>Industry<input name="industry" defaultValue={s(client, "industry")}/></label><label>City<input name="city" defaultValue={s(client, "city")}/></label><label>Payment terms (days)<input name="paymentTermsDays" type="number" min="0" defaultValue={s(client, "paymentTermsDays") || "30"}/></label><label>Status<select name="status" defaultValue={s(client, "status")}><option value="prospect">Prospect</option><option value="active">Active</option><option value="on_hold">On hold</option><option value="won">Won</option><option value="lost">Lost</option></select></label>{(() => { const deal = data.pipeline.find((row) => s(row, "clientId") === s(client, "id") && s(row, "stage") !== "lost"); return deal ? <label>Pipeline stage<select name="stage" defaultValue={s(deal, "stage")}>{stages.map((st) => <option key={st} value={st}>{stageLabels[st]}</option>)}</select></label> : null; })()}<label className="wide">Notes<textarea name="notes" defaultValue={s(client, "notes")}/></label><div className="form-actions"><button className="ghost" type="button" onClick={onClose}>Cancel</button><button className="primary">Save changes</button></div></form></section></div>; }

function RevenueActualDialog({ revenue, client, onClose, onSave }: { revenue: Row; client: (id: string) => string; onClose: () => void; onSave: (e: FormEvent<HTMLFormElement>) => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">REVENUE UPDATE</p><h2>Update actual revenue</h2><p>{client(s(revenue, "clientId"))} · projected {m.format(projected(revenue))} · margin {Math.round(projectedMargin(revenue) / Math.max(1, projected(revenue)) * 100)}%</p></div><form className="crm-form" onSubmit={onSave}><label>Actual revenue<input name="actualRevenue" type="number" min="0" defaultValue={actual(revenue) === null ? "" : actual(revenue) || ""} required/></label><p className="form-hint">Actual margin is calculated from the projected margin percentage. Saving replaces the previous actual value.</p><div className="form-actions"><button className="ghost" type="button" onClick={onClose}>Cancel</button><button className="primary">Save actual</button></div></form></section></div>; }

function CallImportDialog({ preview, onFile, onClose, onSave }: { preview: { row: Record<string, string>; error: string }[]; onFile: (file: File) => void; onClose: () => void; onSave: () => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal wide-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">BULK IMPORT</p><h2>Upload calls</h2><p>Upload a CSV or Excel export. Preview and fix row-level errors before saving.</p></div><label className="upload-drop">Choose Excel / CSV<input type="file" accept=".csv,.xlsx,.xls" onChange={(e) => e.target.files?.[0] && onFile(e.target.files[0])}/></label>{preview.length > 0 && <div className="import-preview"><TableHead cols={["Client / prospect", "Called at", "Outcome", "Validation"]}/>{preview.map((item, i) => <div className={"table-row " + (item.error ? "error-row" : "")} key={i}><span>{item.row.client || item.row.prospectName || item.row.clientId || "—"}</span><span>{item.row.calledAt || "—"}</span><span>{item.row.outcome || "—"}</span><span>{item.error || "Ready"}</span></div>)}</div>}<div className="form-actions"><button className="ghost" onClick={onClose}>Cancel</button><button className="primary" onClick={onSave} disabled={!preview.length}>Save valid rows</button></div></section></div>; }

function TeamMemberDialog({ team, onClose, onSave }: { team: string; onClose: () => void; onSave: (body: Record<string, string>) => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">TEAM MEMBERS</p><h2>Add member to {team}</h2></div><form className="crm-form" onSubmit={(e) => { e.preventDefault(); onSave(Object.fromEntries(new FormData(e.currentTarget).entries()) as Record<string, string>); }}><label>Full name<input name="fullName" required/></label><label>Real email<input name="email" type="email" required/></label><label>Role<select name="role"><option value="staff">BD member</option><option value="head">Team head</option></select></label><div className="form-actions"><button className="ghost" type="button" onClick={onClose}>Cancel</button><button className="primary">Add member</button></div></form></section></div>; }

function AgreementPanel({ agreement, client, onClose, onSave }: { agreement: Row; client: (id: string) => string; onClose: () => void; onSave: (e: FormEvent<HTMLFormElement>) => void }) { const isImage = s(agreement, "documentMimeType").startsWith("image/"); return <div className="side-panel-backdrop" onClick={onClose}><aside className="side-panel" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><p className="kicker">AGREEMENT VIEW</p><h2>{s(agreement, "title")}</h2><div className="file-preview">{s(agreement, "documentId") ? isImage ? <img alt={s(agreement, "documentName") || "Agreement"} src={"/api/documents/" + s(agreement, "documentId")}/> : <iframe title="Agreement preview" src={"/api/documents/" + s(agreement, "documentId")}/> : <div className="file-placeholder">No file uploaded</div>}</div><div className="agreement-facts"><p><b>Parties</b><span>{client(s(agreement, "clientId"))} and SecondMedic</span></p><p><b>Start date</b><span>{fmtDate(s(agreement, "effectiveDate"))}</span></p><p><b>Expiry date</b><span>{fmtDate(s(agreement, "expiryDate"))}</span></p><p><b>Value</b><span>{m.format(n(agreement, "valueMinor"))}</span></p></div><form className="crm-form agreement-edit-form" onSubmit={onSave}><label className="wide">Payment terms<textarea name="paymentTerms" defaultValue={s(agreement, "paymentTerms")}/></label><label className="wide">Renewal terms<textarea name="renewalTerms" defaultValue={s(agreement, "renewalTerms")}/></label><label className="wide">Key clauses<textarea name="summary" defaultValue={s(agreement, "summary")}/></label><div className="form-actions"><button type="button" className="ghost" onClick={onClose}>Close</button><button className="primary">Save details</button></div></form></aside></div>; }

function PaymentDialog({ invoice, onClose, onSave }: { invoice: Row; onClose: () => void; onSave: (e: FormEvent<HTMLFormElement>) => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">INVOICE PAYMENT</p><h2>Record payment</h2><p>{s(invoice, "invoiceNumber")} · balance to collect</p></div><form className="crm-form" onSubmit={onSave}><label>Amount received<input name="amount" type="number" min="1" required/></label><label>Payment date<input name="receivedOn" type="date" defaultValue={today()} required/></label><label>Mode<select name="method"><option value="bank_transfer">Bank transfer</option><option value="upi">UPI</option><option value="cash">Cash</option><option value="cheque">Cheque</option></select></label><label>Reference<input name="referenceNo" placeholder="UTR / receipt no."/></label><div className="form-actions"><button type="button" className="ghost" onClick={onClose}>Cancel</button><button className="primary">Save payment</button></div></form></section></div>; }
function PipelineInvoiceDialog({ deal, onClose, onSave }: { deal: Row; onClose: () => void; onSave: (e: FormEvent<HTMLFormElement>) => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">L5 BILLING</p><h2>Create invoice</h2><p>Choose the invoice date for {s(deal, "title")}.</p></div><form className="crm-form" onSubmit={onSave}><label>Invoice date<input name="invoiceDate" type="date" defaultValue={today()} required/></label><div className="form-actions"><button type="button" className="ghost" onClick={onClose}>Cancel</button><button className="primary">Move to L5</button></div></form></section></div>; }
function PipelineSettingsDialog({ settings, onClose, onSave }: { settings?: Row; onClose: () => void; onSave: (values: Record<string, string>) => void }) { let values: Record<string, number> = { l1: 20, l2: 50, l3: 100, l4: 100, l5: 100 }; try { values = { ...values, ...JSON.parse(s(settings, "probabilities")) }; } catch {} return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">ADMIN SETTINGS</p><h2>Stage probabilities</h2></div><form className="crm-form" onSubmit={(e) => { e.preventDefault(); onSave(Object.fromEntries(new FormData(e.currentTarget).entries()) as Record<string, string>); }}>{stages.map((stage) => <label key={stage}>{stageLabels[stage]}<input name={stage} type="number" min="0" max="100" defaultValue={String(values[stage])}/></label>)}<div className="form-actions"><button type="button" className="ghost" onClick={onClose}>Cancel</button><button className="primary">Save settings</button></div></form></section></div>; }
function AuthHelpDialog({ onClose }: { onClose: () => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">ACCOUNT ACCESS</p><h2>Forgot password?</h2><p>Ask your administrator to reset your CRM password. They can issue a temporary password and your next sign-in will require a change.</p></div><div className="form-actions"><button className="primary" onClick={onClose}>Close</button></div></section></div>; }
